-- Let `user.role` hold 'listener' (see $lib/roles): an account that only opens
-- the archive from anywhere. 0004 added `user_role_check` allowing 'admin' and
-- 'contributor' alone; SQLite cannot alter a CHECK in place, so this rebuilds
-- `user` with the check widened, column for column as 0004 left it.
--
-- Widened rather than dropped, although auth.schema.ts (generated by the
-- better-auth CLI) does not declare it and every snapshot since 0006 omits it:
-- better-auth serves POST /api/auth/admin/set-role to any admin and stores
-- whatever text it is given, so this check is what keeps the column to the
-- roles the app knows. The cost is the same drift 0006, 0008, 0009 and 0010
-- already trim by hand: a generated migration will propose dropping it again,
-- and adding a role needs a migration like this one.
--
-- A plain table rebuild with foreign keys off, the pattern of 0004 and 0006, so
-- that dropping the old table does not cascade-delete every `session` and
-- `account` row (migrations.spec.ts replays it over a populated database).
PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_user` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`email` text NOT NULL,
	`email_verified` integer DEFAULT false NOT NULL,
	`image` text,
	`created_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL,
	`updated_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL,
	`role` text,
	`banned` integer DEFAULT false,
	`ban_reason` text,
	`ban_expires` integer,
	CONSTRAINT "user_role_check" CHECK("__new_user"."role" in ('admin', 'contributor', 'listener'))
);
--> statement-breakpoint
